  `performance_2022` enum('Poor','Average','Good','Excellent') DEFAULT 'Poor',
  `performance_2023` enum('Poor','Average','Good','Excellent') DEFAULT 'Poor',
  `performance_2024` enum('Poor','Average','Good','Excellent') DEFAULT 'Poor',
  `accumulative_marks` decimal(5,2) DEFAULT '0.00',
  `average_marks` decimal(5,2) DEFAULT '0.00',
  `accumulative_performance` enum('Poor','Average','Good','Excellent') DEFAULT 'Poor',
  PRIMARY KEY (`staff_id`)
